// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint256 numTos) public {
        vm.assume(numTos > 0 && numTos <= 100);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        address[] memory tos = new address[](numTos);
        uint[] memory values = new uint[](numTos);
        for (uint i = 0; i < numTos; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp)))));
            values[i] = i;
        }
        Helper helper = new Helper();
        address helperAddr = address(helper);
        (bool success, bytes memory ret) = helperAddr.call(
            abi.encodeWithSelector(Helper.proxy.selector, from, caddress, tos, values)
        );
        if (success) {
            bool retVal = abi.decode(ret, (bool));
            assertTrue(retVal);
        }
    }
}

contract Helper {
    function proxy(address from, address caddress, address[] memory _tos, uint[] memory v) external returns (bool) {
        C c = C(msg.sender);
        return c.transfer(from, caddress, _tos, v);
    }
}

