pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Use try/catch to check non-revert and capture the return value
        bool ok;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool _ret) {
            ok = true;
            ret = _ret;
        } catch {
            ok = false;
        }
        // If it didn't revert, the return value must be true
        assertTrue(!ok || ret, "transfer return value must be true when it does not revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint[] memory vs) public {
        // 1. Restrict to admissible domain
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vs.length);
        // Ensure caddress is not a precompile that might revert on low-level call
        vm.assume(caddress != address(this) && caddress != address(c));
        // avoid excessively large arrays causing out-of-gas
        vm.assume(tos.length <= 10);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        // 2. Drive the transfer call and capture the return value
        bool returned;
        try c.transfer(from, caddress, tos, vs) returns (bool result) {
            returned = result;
        } catch {
            // if it reverts, skip the assertion (only non-reverting calls are in scope)
            return;
        }

        // 3. Assert that for any non-reverting call, the return value is true
        assertTrue(returned);
    }
}

